struct Store:AssetStore {std::vector<std::unique_ptr<FileAssets>> roots;void add(const std::filesystem::path&p){roots.push_back(std::make_unique<FileAssets>(p.string()));}std::unique_ptr<AssetFile>open(std::string_view n)override{for(auto&r:roots)if(auto f=r->open(n))return f;return {};}};
SourceValue luaData(const std::filesystem::path&p){auto*L=luaL_newstate();if(luaL_loadfile(L,p.c_str())||lua_pcall(L,0,1,0))throw std::runtime_error(lua_tostring(L,-1));SourceValue s;std::string e;if(!readSourceValue(L,-1,s,e))throw std::runtime_error(e);lua_close(L);return s;}
