 if(argc!=2)throw std::runtime_error("action_stop_world_smoke HADES_ROOT");const std::filesystem::path root=argv[1],assets=root/".local/native-assets";Store hero;hero.add(assets/"hero-actions-v4");hero.add(assets/"hero-markers-v4");ActorAnimationBank heroBank;heroBank.load(hero);ActorMarkerBank markers;markers.load(hero,heroBank);ActorAnimationPlayback playback;playback.play(heroBank,"ZagreusSwordRunStop");
 Store action;action.add(assets/"action-effects-v3");auto bank=std::make_shared<ActorAnimationBank>();bank->load(action,"action-effect-frames.bin");auto registry=std::make_shared<AnimationRegistry>();ActionEffectWorld world;std::string error;require(world.load(luaData(assets/"action-effects-v3/action-effects.lua"),bank,registry,error),error);
 Store audioAssets;for(const auto*n:{"audio-streams-movement-stop-v1"})audioAssets.add(assets/n);AudioWorld audio(&audioAssets);require(audio.loadCatalog(luaData(assets/"audio-events-opening-v12/audio-events.lua"),error),error);
 const auto events=luaData(root/".local/native-build/assets/actor-animation-events.lua");std::set<std::string> created;uint32_t markerCalls=0,sounds=0,eventsRun=0;uint64_t uniforms=0,coins=0;double energy=0;EffectOwnerState owner;owner.lifetime=100;owner.x=1947.37f;owner.y=5188.61f;owner.scale=.7f;owner.angle=.8f;owner.baseColor=std::array<uint8_t,4>{255,255,255,255};owner.baseHsv=std::array<float,4>{0,0,0,0};ActionEffectProviders p;
 p.owner=[&](int32_t id,EffectOwnerState&o,std::string&){if(id!=40000)return false;o=owner;return true;};p.random=[&](double&v,std::string&){v=.25;++uniforms;return true;};p.bounded=[&](uint32_t n,uint32_t&v,std::string&){v=n/2;++coins;return n>0;};p.elapsed=[](int32_t,float,float dt,float&r,std::string&){r=dt;return true;};p.marker=[&](int32_t,const std::string&name,std::array<float,3>&point,std::string&){const auto clip=playback.clipIndex();ActorMarkerTransform t;t.resolved=true;t.locationX=owner.x;t.locationY=owner.y;t.attachedThingZ=owner.z;markers.applySourceTransform(clip,owner.scale,1,t);const auto mp=markers.sample(clip,playback.originalFrame(),heroBank.originalAngleForFacing(clip,owner.angle),name);const auto xy=ActorMarkerBank::location(mp,t);point={xy[0],xy[1],owner.z};++markerCalls;return true;};p.sound=[&](const std::string&cue,int32_t,const std::array<float,3>&pos,uint32_t cap,uint32_t&id,std::string&e){if(cap!=0||(cue!="/Leftovers/SFX/WingFlapMedium"&&cue!="/Leftovers/SFX/PowerUpFwoosh")){e="Unexpected actual first-action sound";return false;}if(!audio.createCue(cue,AudioSource{false,pos[0],pos[1],pos[2]},id,e)||!audio.play(id,e))return false;++sounds;return true;};
