 p.worldFrame=2;onSlide(*playback.clip(),playback.clip()->slides.at(playback.slideIndex()));observe();bool scaleTransitionObserved=false,skewObserved=false;size_t leaves=0;size_t peak=world.states().size();
 for(unsigned frame=0;frame<180;++frame){p.worldFrame=frame+3;if(!playback.finished())playback.advance(1./60,1,onSlide);require(world.advance(1.f/60,p,error),error);uint32_t frameSpawned=0;require(world.updateTime(1.f/60,p,frameSpawned,error),error);leaves+=frameSpawned;if(frameSpawned>2)throw std::runtime_error("First action time cap admission");for(const auto&[h,s]:world.states())if(s.name=="WeaponStopParticlesSword"&&s.fraction>0){ActorVisual v;require(world.visual(h,owner,{255,255,255,255},v,error),error);if(v.scale<s.ownScale)scaleTransitionObserved=true;if(std::abs(v.meshTransform[0]-1)>.01f||std::abs(v.meshTransform[2])>.01f)skewObserved=true;}observe();peak=std::max(peak,world.states().size());float pcm[1600];require(audio.render(pcm,800,error),error);for(float x:pcm){if(!std::isfinite(x))throw std::runtime_error("Nonfinite original footstep PCM");energy+=double(x)*x;}}
